            for p2 in ps[i+1:]:
                dr,dc=p2[0]-p1[0],p2[1]-p1[1]
                if abs(dr)==abs(dc) and dr!=0:
                    dirs.add((dr,dc) if dr>0 else (-dr,-dc))
