            line=sorted(p for p in ps if any((p[0]-q[0],p[1]-q[1]) in ((dr,dc),(-dr,-dc)) for q in ps))
            if len(line)<2: continue
            # free runs from each end
            def run(start,step):
                n=0; rr,cc=start[0]+step[0],start[1]+step[1]
                while 0<=rr<H and 0<=cc<W and g[rr][cc]==bg:
                    n+=1; rr+=step[0]; cc+=step[1]
                return n
            nf=run(line[-1],(dr,dc)); nb=run(line[0],(-dr,-dc))
            if nf==nb: continue
            step=(dr,dc) if nf>nb else (-dr,-dc)
            start=line[-1] if nf>nb else line[0]
            rr,cc=start[0]+step[0],start[1]+step[1]
            while 0<=rr<H and 0<=cc<W and g[rr][cc]==bg:
                out[rr][cc]=col; rr+=step[0]; cc+=step[1]
    return out

